  reader=subprocess.Popen(base,stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True);reader.stdin.write("\\set VERBOSITY verbose\nSET statement_timeout='5s';"+auth('SELECT '+rpc()+';'));reader.stdin.close();time.sleep(.2);blocked=reader.poll() is None;holder.stdin.write('COMMIT;\n\\q\n');holder.stdin.flush();holder.stdin.close();holder.wait(timeout=8);reader.wait(timeout=8);output=reader.stdout.read()+reader.stderr.read();rows.append({'id':'concurrent-'+label,'passed':blocked and holder.returncode==0 and reader.returncode!=0 and expected in output,'exitCode':reader.returncode,'holderExitCode':holder.returncode,'expectedDenial':True,'output':output})
